  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// New tests for Issue #1: Brick Bounces

// Helper to simulate brick collision and bounce
function simulateBrickHit(ball, brick, state = { level: 1 }) {
  // In the current game, brick collision is handled in frame().
  // Since we want to test it, and it's currently in frame, we can't easily
  // call it without a canvas. We will move the logic to a separate function
  // in neon.js as suggested by ISSUE.md #2, but for now, we'll define how
  // the test should look once we've refactored.
}

test('brick bounce: hit top face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  // Ball hitting the top of the brick
  state.ball = { x: 125, y: 100 - 7, r: 7, vx: 0, vy: 200 };

  // We will call a brickHit function once we implement it
  // For now, we just define the expectation
  // After hit: vy should be UP, y should be pushed out
});

test('brick bounce: hit bottom face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.ball = { x: 125, y: 120 + 7, r: 7, vx: 0, vy: -200 };
  // Expect: vy should be DOWN, y pushed out
});

test('brick bounce: hit left face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.ball = { x: 100 - 7, y: 110, r: 7, vx: 200, vy: 0 };
  // Expect: vx should be LEFT, x pushed out
});

test('brick bounce: hit right face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.ball = { x: 150 + 7, y: 110, r: 7, vx: -200, vy: 0 };
  // Expect: vx should be RIGHT, x pushed out
});

test('brick bounce: corner hit', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  // Ball hitting top-left corner precisely
  state.ball = { x: 100 - 4, y: 100 - 4, r: 7, vx: 200, vy: 200 };
  // Expect: both vx and vy flipped
});

test('brick bounce: tunneling prevention (sweep)', () => {
  const state = createState(1);
