import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  collides,
  step,
  makeBricks,
  createState,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
  UP,
  DOWN,
  LEFT,
  RIGHT,
  resolveBrickCollision,
} from './neon.js';

test('collides: clear overlap detected', () => {
  const ball = { x: 100, y: 100, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('collides: ball clearly away => no collision', () => {
  const ball = { x: 300, y: 300, r: 8 };
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), false);
});

test('collides: edge contact (radius) detected', () => {
  const ball = { x: 85, y: 100, r: 8 }; // right edge of the ball at 93 > 90
  const brick = { x: 90, y: 90, w: 40, h: 20 };
  assert.equal(collides(ball, brick), true);
});

test('step: bounce off the left wall', () => {
  const state = createState(1);
  state.ball = { x: 2, y: 200, r: 7, vx: -300, vy: 0 };
  step(state, 1 / 60);
  assert.ok(state.ball.vx > 0, 'horizontal velocity should flip to the right');
});

test('step: ball exiting through the bottom => lost', () => {
  const state = createState(1);
  state.ball = { x: 320, y: 500, r: 7, vx: 0, vy: 400 };
  const lost = step(state, 1 / 60);
  assert.equal(lost, true);
});

test('makeBricks: full, all-alive grid at start', () => {
  const bricks = makeBricks(1);
  assert.equal(bricks.length, BRICK_ROWS * BRICK_COLS);
  assert.ok(bricks.every((b) => b.alive));
  assert.ok(bricks.every((b) => b.x >= 0 && b.x + b.w <= WIDTH));
});

// New tests for Issue #1: Brick Bounces

test('brick bounce: hit top face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  // Ball hitting the top of the brick
  state.ball = { x: 125, y: 100 - 7 + 2, r: 7, vx: 0, vy: 200 };

  resolveBrickCollision(state, brick);

  assert.equal(state.ball.vy, -200);
  assert.ok(state.ball.y <= 100 - 7, 'Ball should be pushed out to the top');
  assert.equal(brick.alive, false);
});

test('brick bounce: hit bottom face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  // Ball hitting the bottom of the brick
  state.ball = { x: 125, y: 120 + 7 - 2, r: 7, vx: 0, vy: -200 };

  resolveBrickCollision(state, brick);

  assert.equal(state.ball.vy, 200);
  assert.ok(state.ball.y >= 120 + 7, 'Ball should be pushed out to the bottom');
  assert.equal(brick.alive, false);
});

test('brick bounce: hit left face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  // Ball hitting the left of the brick
  state.ball = { x: 100 - 7 + 2, y: 110, r: 7, vx: 200, vy: 0 };

  resolveBrickCollision(state, brick);

  assert.equal(state.ball.vx, -200);
  assert.ok(state.ball.x <= 100 - 7, 'Ball should be pushed out to the left');
  assert.equal(brick.alive, false);
});

test('brick bounce: hit right face', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, java: true, alive: true }; // added java:true to avoid confusion, not related
  const brick_fixed = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.ball = { x: 150 + 7 - 2, y: 110, r: 7, vx: -200, vy: 0 };

  const state_fixed = createState(1);
  state_fixed.ball = { x: 150 + 7 - 2, y: 110, r: 7, vx: -200, vy: 0 };

  resolveBrickCollision(state_fixed, brick_fixed);

  assert.equal(state_fixed.ball.vx, 200);
  assert.ok(state_fixed.ball.x >= 150 + 7, 'Ball should be pushed out to the right');
  assert.equal(brick_fixed.alive, false);
});

test('brick bounce: corner hit', () => {
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  // Ball hitting top-left corner precisely (overlaps 2px in both X and Y)
  state.ball = { x: 100 - 7 + 2, y: 100 - 7 + 2, r: 7, vx: 200, vy: 200 };

  resolveBrickCollision(state, brick);

  assert.equal(state.ball.vx, -200);
  assert.equal(state.ball.vy, -200);
  assert.ok(state.ball.x <= 100 - 7, 'Ball should be pushed out');
  assert.ok(state.ball.y <= 100 - 7, 'Ball should be pushed out');
});

test('brick bounce: tunneling prevention (sweep)', () => {
  // Tunnelling is when the ball moves so fast it skips over the brick.
  // This requires modifying step() to check for collisions between 
  // previous position and current position (swept AABB).
  // Since the user asked to fix "plows through" and "tunneling" in ISSUE.md,
  // I need to implement a swept collision check.

  // For now, let's see if it fails.
  const state = createState(1);
  const brick = { x: 100, y: 100, w: 50, h: 20, alive: true };
  state.ball = { x: 125, y: 80, r: 7, vx: 0, vy: 1000 }; 

  // We simulate a step of 50ms (the max dt in loop)
  const dt = 0.05;

  // This is currently not implemented in step().
  // Let's just test it.
  const oldY = state.ball.y;
  step(state, dt);

  // The ball should have hit the brick between 80 and 80 + 1000*0.05 = 130.
  // The brick is at 100.
  // It should be deflected.
  assert.ok(state.ball.vy < 0, 'Ball should have been deflected by brick during fast movement');
});

