// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;

  // Store previous position for tunneling prevention
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Tunnelling prevention: check if the ball passed through any live brick
  // between the previous and current positions.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    // Simple AABB sweep: check if the ball's bounding box for the whole step
    // overlaps the brick.
    const stepMinX = Math.min(prevX - ball.r, ball.x - ball.r);
    const stepMaxX = Math.max(prevX + ball.r, ball.x + ball.r);
    const stepMinY = Math.min(prevY - ball.r, ball.y - ball.r);
    const stepMaxY = Math.max(prevY + ball.r, ball.y + ball.r);

    if (stepMaxX > brick.x && stepMinX < brick.x + brick.w &&
        stepMaxY > brick.y && stepMinY < brick.y + brick.h) {

      // If it's actually colliding now, resolve it.
      if (collides(ball, brick)) {
        resolveBrickCollision(state, brick);
        continue;
      }

      // Otherwise, it might have tunnelled.
      // We check if it crossed the brick's boundaries.
      const crossedY = (prevY + ball.r < brick.y && ball.y - ball.r > brick.y + brick.h) ||
                       (prevY - ball.r > brick.y + brick.h && ball.y + ball.r < brick.y);
      const crossedX = (prevX + ball.r < brick.x && ball.x - ball.r > brick.x + brick.w) ||
                       (prevX - ball.r > brick.x + brick.w && ball.x + ball.r < brick.x);

      if (crossedY && (ball.x + ball.r > brick.x && ball.x - ball.r < brick.x + brick.w)) {
        ball.y = prevY + ball.r < brick.y ? brick.y - ball.r : brick.y + brick.h + ball.r;
        resolveBrickCollision(state, brick);
        break;
      }
      if (crossedX && (ball.y + ball.r > brick.y && ball.y - ball.r < brick.y + brick.h)) {
        ball.x = prevX + ball.r < brick.x ? brick.x - ball.r : brick.x + brick.w + ball.r;
        resolveBrickCollision(state, brick);
        break;
      }
    }
  }

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle
  if (
    ball.vy > 0 &&
    ball.y + ball.r >= paddle.y &&
    ball.y + ball.r <= paddle.y + paddle.h &&
    ball.x >= paddle.x &&
    ball.x <= paddle.x + paddle.w
  ) {
    ball.y = paddle.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
    // The rebound angle depends on where the paddle was hit.
    const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
    ball.vx = ballSpeed(state.level) * 0.6 * hit;
    state.combo = 0; // touching the paddle resets the combo
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

